<header class="properties-page-header"><div><h1>Contatos inválidos</h1><p>Leads e proprietários sinalizados para revisão dos dados de contato.</p></div></header>
<?php foreach(['leads'=>'Leads','owners'=>'Proprietários'] as $type=>$label): $records=$$type; ?><section><h2><?= $e($label) ?> <small>(<?= count($records) ?>)</small></h2><?php if(!$records): ?><p>Nenhum contato sinalizado.</p><?php else: ?><div class="properties-table-wrap"><table><thead><tr><th>Nome</th><th>Telefone</th><th>E-mail</th><th>Ação</th></tr></thead><tbody><?php foreach($records as $item): ?><tr><td><a href="/<?= $e($type) ?>/<?= (int)$item['id'] ?>"><?= $e($item['name']) ?></a></td><td><?= $e($item['phone'] ?: '—') ?></td><td><?= $e($item['email'] ?: '—') ?></td><td><form method="post" action="/contacts/<?= $e($type) ?>/<?= (int)$item['id'] ?>/invalid"><?= $csrfField ?><input type="hidden" name="return_to" value="/contacts/invalid"><input type="hidden" name="invalid_contact" value="0"><button class="outline secondary">Remover rótulo</button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endforeach ?>
